#!/usr/bin/env bash
# recipes/crate-unicode-segmentation--1-10-1/build.sh -- stage the unicode-segmentation 1.10.1 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/unicode-segmentation-1.10.1"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"1dd624098567895118886609431a7c3b8f516e41d30e0643f03d94592a147e36"}\n' > "${dest}/.cargo-checksum.json"
